/* DShot600 bit timing, referenced to a 600kHz bit rate.
 * Each bit period = 1 / 600kHz = 1.667us.
 * Encoding: duty-cycle-based — a '1' bit has a longer high pulse,
 * a '0' bit has a shorter high pulse, both within the same bit period. */

#define DSHOT600_BIT_PERIOD_NS   1667   /* total time per bit, ns */
#define DSHOT600_T1H_NS          1250   /* high time for a logic '1' bit */
#define DSHOT600_T0H_NS           625   /* high time for a logic '0' bit */

/* Frame structure (16 bits total, sent MSB first):
 *   11 bits : throttle value (0 = disarmed/no-op, 48-2047 = throttle range,
 *             1-47 reserved for special commands e.g. beep, save settings)
 *    1 bit  : telemetry request flag
 *    4 bits : CRC (XOR-based checksum over the previous 12 bits)
 */
typedef struct {
    uint16_t throttle   : 11;
    uint16_t telem_req  : 1;
    uint16_t crc        : 4;
} DShotFrame_t;

uint8_t DShot_ComputeCRC(uint16_t throttle_and_telem)
{
    /* XOR nibbles of the 12-bit value together, per DShot spec */
    uint8_t crc = (throttle_and_telem ^ (throttle_and_telem >> 4) ^
                   (throttle_and_telem >> 8)) & 0x0F;
    return crc;
}
```

On the PIC side, these timings are typically generated via a hardware PWM/timer peripheral configured for the bit period, with duty cycle swapped per-bit between T1H and T0H — not bit-banged in software, since 1.667us periods leave very little margin for interrupt jitter on an 8-bit core. The CRC exists specifically so the ESC can reject a corrupted throttle command instead of acting on garbage — important since a bad throttle value sent to one motor could destabilize the whole aircraft.

```c
/* STM32F7 - TIM6 configured to fire an interrupt at exactly 8kHz,
 * driving the PID control loop. Assumes 216MHz SYSCLK, APB1 timer
 * clock at 108MHz (adjust PSC/ARR to your actual clock tree). */

TIM_HandleTypeDef htim6;

void PID_Timer_Init(void)
{
    __HAL_RCC_TIM6_CLK_ENABLE();

    /* Target: 8000 Hz interrupt rate.
     * Timer clock (post-prescaler) = 108MHz / (PSC+1)
     * ARR chosen so (timer_clock / (ARR+1)) == 8000 Hz */
    htim6.Instance = TIM6;
    htim6.Init.Prescaler = 107;           /* 108MHz / 108 = 1MHz timer tick */
    htim6.Init.Period    = 124;           /* 1MHz / 125 = 8kHz */
    htim6.Init.CounterMode = TIM_COUNTERMODE_UP;

    HAL_TIM_Base_Init(&htim6);
    HAL_TIM_Base_Start_IT(&htim6);

    /* Enable FPU explicitly (usually already on via CMSIS startup,
     * but confirm CPACR bits for full-speed context save of FPU regs) */
    SCB->CPACR |= (0xF << 20);
}

/* Fires every 125us (8kHz). Keep this ISR tight: read sensors,
 * run PID math, write motor outputs, exit. */
void TIM6_DAC_IRQHandler(void)
{
    if (__HAL_TIM_GET_FLAG(&htim6, TIM_FLAG_UPDATE)) {
        __HAL_TIM_CLEAR_FLAG(&htim6, TIM_FLAG_UPDATE);

        float gx, gy, gz;
        Gyro_ReadFloat(&gx, &gy, &gz);      /* hardware FPU makes this cheap */

        float motor_out[4];
        PID_Compute(gx, gy, gz, motor_out); /* single-precision float math,
                                                runs on FPU in ~single-digit
                                                cycles per op, not emulated */

        Motors_SetOutput(motor_out);
    }
}
```

The reason this is worth calling out on F7 specifically vs F4: at 8kHz (125us budget per loop), every microcycle spent on float emulation would eat directly into your margin — the hardware FPU is what makes 8kHz+ looptimes with real filtering feasible at all.

